@import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,300;0,400;0,500;0,600;0,700;1,300;1,400;1,500;1,600;1,700&display=swap');
@import url('https://fonts.googleapis.com/css2?family=Roboto+Flex:opsz,wght@8..144,100..1000&display=swap');

@font-face {
    font-family: "KNIGHT WARRIOR";
    src: url(./assets/KnightWarrior-w16n8.otf);
}

body {
    margin: 0;
    padding: 0;
    overflow: hidden; 
    box-sizing: border-box;
}

.body {
    height: 100vh;
    width: 100%;
    background-image: linear-gradient( rgba(0, 0, 0, 0.5), rgba(0, 0, 0, 0.904)), url('./assets/taneli-lahtinen-bJiisZmEB2M-unsplash.jpg');
    background-position: center center;
    background-size: cover;
    background-repeat: no-repeat;
    overflow: hidden;
}

.navbar {
    display: flex;
    justify-content: space-between;
    padding: 20px 4rem;
    align-items: center; 
}

.navbar .nav-image {
    display: flex;
    height: 70px;
    align-items: center;
}

.navbar .nav-image h5 {
    font-family: "Cormorant Garamond", system-ui;
    font-size: 40px;
    color: #fff;
    font-weight: 700;
}

.navbar img {
    height: 30px;
    width: 30px;
}

.navbar .nav-list {
    display: flex;
    align-items: center;
    width: 500px;
    margin-bottom: -10px;
}

.navbar .nav-list li {
    list-style-type: none;
    margin-right: 50px;
    width: 80px;
    font-family: "poppins" sans-serif;
}

.navbar .nav-list a {
    transition: all 0.5s ease-in-out;
    color: #ffffffaf;
    text-decoration: none;
    font-size: 25px;
    font-weight: 400;
}

.navbar .nav-list a:hover {
    color: #ffffff;
    transition: all 0.5s ease-in-out;
    font-weight: 700;
    font-size: 26px;
}

#closeMenu{
    display: none;
}


.main-container{
    height: 82%;
    display: flex;
    justify-content: center;
    align-items: end;
}

.main-container .left{
    width: 35%; 
    padding-left: 50px;
    height: 70%;
    align-items: center;
}

.main-container .left h1{
    font-family: "Cormorant Garamond", system-ui;
    font-weight: 900;
    font-style: normal;
    font-size: 80px;
    color: #fff;
    line-height: normal;
}

.main-container .left p{
    color: #fff;
    font-family: "Cormorant Garamond" sans-serif;
    font-size: 16px;
    height: 100px;
    font-weight: 400;
}

.main-container .left button{  
    font-family: "Cormorant Garamond", system-ui;
    font-style: normal;
    border-radius: 12px;
    border: none;
    font-size: 22px;
    font-weight: 700;
    padding: 17px 34px;
    background-color: #50B61B;
    margin-top: 20px;
    color: #fff;
    cursor: pointer;
}

.main-container .left button:hover{  
    transition: all 0.5s ease;
    background-color: #2f720b;
    color: #fff;
}

.main-container .right{
    width: 55%; 
    height: fit-content;
    position: relative;
}


footer{
    align-items: end;
    height: 50px;
    width: 100%;
    padding: 0px 4rem;
}
footer p{
    font-family: "KNIGHT WARRIOR";
    color: #fff;
    font-stretch: extra-expanded;
}


@media only screen and (max-width: 991px) {

    .navbar {
        justify-content: space-between;
        padding: 20px 3rem; 
    }
    .navbar .nav-image h5 {
        font-size: 30px;
    }
    .navbar img {
        height: 30px;
        width: 30px;
    }
    .navbar .nav-list {
        position: fixed;
        top: 0;
        right: 0;
        width: 200px;
        height: 100vh;
        background-color: rgba(0, 0, 0, 0.8);
        /* display: none;  */
        transform: translateX(250px);
        transition: all 0.5s ease-in-out;
        flex-direction: column;
        align-items: flex-start;
        padding: 20px;
    }
    .navbar .nav-list.show {
        transform: translateX(0px);
        transition: all 0.5s ease-in-out;
        /* display: block; */
    }
    #closeMenu{
        margin: 20px;
        margin-bottom: 50px;
        display: block;
        font-size: 20px;
        margin-left: auto;
        cursor: pointer;
        font-size: 30px;
        color: white;
    }
    .navbar .nav-list li {
        margin-right: 0px;
        margin-bottom: 20px;
        width: auto;
    }
    .navbar .nav-list a {
        font-size: 20px;
        color: white; 
    }
    .navbar .nav-list a:hover {
        font-size: 21px;
    }
    
    .navbar .hamburger {
        display: block;
        cursor: pointer;
    }

   
}


.hamburger {
    display: none; 
    flex-direction: column;
    cursor: pointer;
}

.hamburger div {
    width: 25px;
    height: 3px;
    background-color: white;
    margin: 5px 0;
    transition: 0.4s;
}



.glide{
      height:fit-content;
}

.glide__track{
 height: fit-content;
 align-items: center;
}

.glide__slides{
    align-items: center;
    height: 400px;
}

.glide__slide{

    height: 100%;

}



/* Transition  */
.body {
    transition: background-image 1s ease-in-out;
}

.left {
    position: relative;
}

.left h1, .left p {
    transition: transform 0.5s ease-in-out, opacity 0.5s ease-in-out;
}

.slide-enter {
    /* transform: translateY(100%); */
    opacity: 0;
}

.slide-enter-active {
    /* transform: translateY(0); */
    opacity: 1;
}




.glide__slide div{
    width: 100%;
    height:100%;
    background-size: cover;
    background-position: center center;
    background-repeat: no-repeat;
    border-radius: 20px;
}


.glide__slide--active {
    transform: scale(1.1);
    border: 5px solid #ffffff; /* Add a white border to the active slide */
    box-shadow: 0 4px 15px rgba(0, 0, 0, 0.2); /* Optional: add shadow for better visibility */
    z-index: 1; /* Bring the active slide to the front */
}

.glide__slide {
    transition: transform 0.3s ease-in-out, border 0.3s ease-in-out; /* Smooth transition for scaling and border */
}

/* Optional: Decrease size for non-active slides for more visual contrast */
.glide__slide:not(.glide__slide--active) {
    transform: scale(0.9); /* Scale down non-active slides */
    opacity: 0.8; /* Optional: slightly reduce opacity */
}
